WITH vendas AS (
 SELECT p.id_cliente, p.id_pedido,
        SUM(i.qtd_sacos*i.peso_saco_kg*i.preco_kg) AS receita
 FROM pedidos p JOIN itens_pedido i ON i.id_pedido=p.id_pedido
 WHERE p.status='Faturado'
 GROUP BY p.id_cliente, p.id_pedido
), ranking AS (
 SELECT *, ROW_NUMBER() OVER (
   PARTITION BY id_cliente ORDER BY receita DESC, id_pedido
 ) AS pos FROM vendas
)
SELECT id_cliente,id_pedido,receita FROM ranking
WHERE pos=1 ORDER BY id_cliente;

