def calcular_carga(sacos, peso_saco_kg, preco_kg):
    if sacos <= 0 or peso_saco_kg <= 0 or preco_kg < 0:
        raise ValueError("Confira quantidades e preço")
    peso = sacos * peso_saco_kg
    return {"peso_kg": peso, "receita": round(peso * preco_kg, 2)}

print(calcular_carga(10, 25, 1.30))
